INSERT INTO "Car" ("slug", "brand", "model", "year", "pricePerDay", "fuel", "seats", "horsepower", "acceleration", "topSpeed", "transmission", "drive", "range", "city", "pickupAddress", "pickupLat", "pickupLng", "hostName", "hostRating", "hostTrips", "description", "descriptionRo", "descriptionRu", "features", "updatedAt") VALUES ('porsche-911-carrera-4s', 'Porsche', '911 Carrera 4S', 2024, 6800, 'Petrol'::"Fuel", 4, 443, 3.6, 306, '8-speed PDK automatic', 'AWD'::"Drive", NULL, 'Chișinău', 'Bulevardul Ștefan cel Mare și Sfânt 134, Chișinău', 47.0233, 28.835, 'Lukas W.', 4.9, 212, 'The everyday supercar. All-wheel drive keeps the Carrera 4S planted in any weather, while the twin-turbo flat-six pulls hard all the way to the redline. Comfortable enough for a long weekend, sharp enough for a mountain pass.', 'Supercarul de fiecare zi. Tracțiunea integrală ține Carrera 4S lipit de drum pe orice vreme, iar motorul boxer twin-turbo trage puternic până la limita de turații. Destul de confortabil pentru un weekend lung, destul de precis pentru un drum de munte.', 'Суперкар на каждый день. Полный привод уверенно держит Carrera 4S на дороге в любую погоду, а оппозитная «шестёрка» с двумя турбинами мощно тянет до самой отсечки. Достаточно комфортен для долгих выходных и достаточно точен для горного серпантина.', ARRAY['Sport Chrono package', 'Bose surround sound', 'Apple CarPlay', 'Heated seats', 'Adaptive cruise control', 'Parking camera'], CURRENT_TIMESTAMP);
INSERT INTO "CarPhoto" ("carId", "url", "position") SELECT "id", p.url, p.position FROM "Car", (VALUES ('photo-1611821064430-0d40291d0f0b', 0), ('photo-1633348572662-1cf11058426e', 1), ('photo-1633348570573-2c70fe9129de', 2), ('photo-1613978148487-6d5aa7644585', 3)) AS p(url, position) WHERE "slug" = 'porsche-911-carrera-4s';
INSERT INTO "Car" ("slug", "brand", "model", "year", "pricePerDay", "fuel", "seats", "horsepower", "acceleration", "topSpeed", "transmission", "drive", "range", "city", "pickupAddress", "pickupLat", "pickupLng", "hostName", "hostRating", "hostTrips", "description", "descriptionRo", "descriptionRu", "features", "updatedAt") VALUES ('ferrari-roma-spider', 'Ferrari', 'Roma Spider', 2024, 15600, 'Petrol'::"Fuel", 4, 620, 3.4, 320, '8-speed dual-clutch', 'RWD'::"Drive", NULL, 'Chișinău', 'Strada Columna 106, Chișinău', 47.0271, 28.8356, 'Giulia R.', 5, 64, 'La nuova dolce vita, with the roof down. The soft top folds in 13 seconds at up to 60 km/h, and the front-mounted V8 delivers effortless grand-touring pace. Made for roads through the vineyards and long lunches.', 'La nuova dolce vita, cu plafonul coborât. Capota din pânză se pliază în 13 secunde la viteze de până la 60 km/h, iar motorul V8 montat în față oferă un ritm de grand tourer fără efort. Făcută pentru drumuri printre podgorii și prânzuri lungi.', 'La nuova dolce vita — с опущенной крышей. Мягкий верх складывается за 13 секунд на скорости до 60 км/ч, а V8 спереди обеспечивает лёгкий темп гран-туризмо. Создан для дорог среди виноградников и долгих обедов.', ARRAY['Retractable soft top', 'Wind deflector', 'Passenger display', 'Heated seats', 'Apple CarPlay', 'Front lift system'], CURRENT_TIMESTAMP);
INSERT INTO "CarPhoto" ("carId", "url", "position") SELECT "id", p.url, p.position FROM "Car", (VALUES ('photo-1666790995628-9b55f65cdeeb', 0), ('photo-1645028875875-d3611dc96fe0', 1), ('photo-1687599891000-cf8af5ae4386', 2), ('photo-1643422487068-e3b0202c6b7c', 3)) AS p(url, position) WHERE "slug" = 'ferrari-roma-spider';
INSERT INTO "Car" ("slug", "brand", "model", "year", "pricePerDay", "fuel", "seats", "horsepower", "acceleration", "topSpeed", "transmission", "drive", "range", "city", "pickupAddress", "pickupLat", "pickupLng", "hostName", "hostRating", "hostTrips", "description", "descriptionRo", "descriptionRu", "features", "updatedAt") VALUES ('bmw-m4-competition', 'BMW', 'M4 Competition', 2023, 4600, 'Petrol'::"Fuel", 4, 503, 3.9, 290, '8-speed M Steptronic', 'RWD'::"Drive", NULL, 'Bălți', 'Strada Independenței 33, Bălți', 47.7573, 27.9233, 'Jonas K.', 4.8, 187, 'A proper driver''s coupe. The straight-six sings, the rear-wheel-drive chassis is playful yet precise, and the M carbon bucket seats hold you in place. Four real seats make it surprisingly practical.', 'Un coupé adevărat pentru pasionați. Motorul cu șase cilindri în linie cântă, șasiul cu tracțiune spate e jucăuș, dar precis, iar scaunele sport M din carbon te țin bine pe loc. Patru locuri reale îl fac surprinzător de practic.', 'Настоящее купе для водителя. Рядная «шестёрка» поёт, заднеприводное шасси игривое, но точное, а карбоновые ковши M надёжно держат в повороте. Четыре полноценных места делают его на удивление практичным.', ARRAY['M carbon bucket seats', 'Harman Kardon audio', 'Head-up display', 'Laser headlights', 'Apple CarPlay', 'Parking assistant'], CURRENT_TIMESTAMP);
INSERT INTO "CarPhoto" ("carId", "url", "position") SELECT "id", p.url, p.position FROM "Car", (VALUES ('photo-1682242288217-2c188bd79f0a', 0), ('photo-1660310477229-d03d8565f15d', 1), ('photo-1680102170077-ba515335b8eb', 2), ('photo-1728060838342-cb9744a27d1b', 3)) AS p(url, position) WHERE "slug" = 'bmw-m4-competition';
INSERT INTO "Car" ("slug", "brand", "model", "year", "pricePerDay", "fuel", "seats", "horsepower", "acceleration", "topSpeed", "transmission", "drive", "range", "city", "pickupAddress", "pickupLat", "pickupLng", "hostName", "hostRating", "hostTrips", "description", "descriptionRo", "descriptionRu", "features", "updatedAt") VALUES ('tesla-model-s-plaid', 'Tesla', 'Model S Plaid', 2024, 4200, 'Electric'::"Fuel", 5, 1020, 2.1, 322, 'Single-speed', 'AWD'::"Drive", 600, 'Chișinău', 'Bulevardul Moscova 21, Chișinău', 47.0574, 28.8642, 'Sanne V.', 4.9, 341, 'Hypercar acceleration in a quiet family sedan. Three motors, over 1,000 hp and a long real-world range make the Plaid equally good at school runs and long motorway trips. Supercharger access is included.', 'Accelerație de hypercar într-un sedan de familie silențios. Trei motoare, peste 1.000 CP și o autonomie reală mare fac din Plaid o mașină la fel de bună pentru drumul la școală și pentru călătorii lungi pe autostradă. Accesul la Supercharger este inclus.', 'Разгон гиперкара в тихом семейном седане. Три мотора, более 1000 л. с. и большой реальный запас хода делают Plaid одинаково хорошим и для поездок в школу, и для дальних путешествий по трассе. Доступ к Supercharger включён.', ARRAY['Autopilot', 'Supercharger access', '17" touchscreen', 'Rear-seat display', 'Glass roof', 'Premium audio'], CURRENT_TIMESTAMP);
INSERT INTO "CarPhoto" ("carId", "url", "position") SELECT "id", p.url, p.position FROM "Car", (VALUES ('photo-1536700503339-1e4b06520771', 0), ('photo-1698514340486-cec73815c18d', 1), ('photo-1617704548623-340376564e68', 2), ('photo-1572375180666-c23ef8bef639', 3)) AS p(url, position) WHERE "slug" = 'tesla-model-s-plaid';
INSERT INTO "Car" ("slug", "brand", "model", "year", "pricePerDay", "fuel", "seats", "horsepower", "acceleration", "topSpeed", "transmission", "drive", "range", "city", "pickupAddress", "pickupLat", "pickupLng", "hostName", "hostRating", "hostTrips", "description", "descriptionRo", "descriptionRu", "features", "updatedAt") VALUES ('mercedes-amg-gt-63-s', 'Mercedes', 'AMG GT 63 S', 2023, 7400, 'Petrol'::"Fuel", 4, 630, 3.2, 315, '9-speed MCT', 'AWD'::"Drive", NULL, 'Chișinău', 'Bulevardul Dacia 47, Chișinău', 46.9795, 28.8682, 'Mehmet A.', 4.8, 98, 'A four-door AMG with a hand-built twin-turbo V8. Luxurious and roomy for four adults, yet capable of embarrassing sports cars on a track day. The rear-axle steering makes it feel much smaller than it is.', 'Un AMG cu patru uși și un V8 twin-turbo asamblat manual. Luxos și spațios pentru patru adulți, dar capabil să pună în dificultate mașini sport pe circuit. Direcția pe puntea spate îl face să pară mult mai mic decât este.', 'Четырёхдверный AMG с собранным вручную V8 битурбо. Роскошный и просторный для четырёх взрослых, но способный смутить спорткары на трек-дне. Подруливающая задняя ось делает его гораздо компактнее в ощущениях.', ARRAY['AMG Performance exhaust', 'Burmester audio', 'Massage seats', 'Rear-axle steering', 'Head-up display', '360° camera'], CURRENT_TIMESTAMP);
INSERT INTO "CarPhoto" ("carId", "url", "position") SELECT "id", p.url, p.position FROM "Car", (VALUES ('photo-1622551997608-400d763b0f64', 0), ('photo-1692632146184-08b6f4828a23', 1), ('photo-1633356593834-608fe98620b9', 2), ('photo-1617814076231-2c58846db944', 3)) AS p(url, position) WHERE "slug" = 'mercedes-amg-gt-63-s';
INSERT INTO "Car" ("slug", "brand", "model", "year", "pricePerDay", "fuel", "seats", "horsepower", "acceleration", "topSpeed", "transmission", "drive", "range", "city", "pickupAddress", "pickupLat", "pickupLng", "hostName", "hostRating", "hostTrips", "description", "descriptionRo", "descriptionRu", "features", "updatedAt") VALUES ('lamborghini-huracan-evo', 'Lamborghini', 'Huracán EVO', 2022, 17300, 'Petrol'::"Fuel", 2, 640, 2.9, 325, '7-speed dual-clutch', 'AWD'::"Drive", NULL, 'Chișinău', 'Strada Arborilor 21, Chișinău', 47.0044, 28.8406, 'Alessandro B.', 4.9, 41, 'A naturally aspirated V10 that revs past 8,000 rpm, wrapped in unmistakable Lamborghini lines. Rear-wheel steering and torque vectoring make it approachable, while the sound makes every tunnel an event.', 'Un V10 atmosferic care turează peste 8.000 rpm, îmbrăcat în liniile inconfundabile Lamborghini. Direcția pe roțile spate și vectorizarea cuplului îl fac accesibil, iar sunetul transformă fiecare tunel într-un eveniment.', 'Атмосферный V10, раскручивающийся выше 8000 об/мин, в узнаваемых линиях Lamborghini. Подруливающие задние колёса и векторизация тяги делают его послушным, а звук превращает каждый тоннель в событие.', ARRAY['Front-axle lift', 'Carbon ceramic brakes', 'Sensonum audio', 'Apple CarPlay', 'Parking camera', 'Launch control'], CURRENT_TIMESTAMP);
INSERT INTO "CarPhoto" ("carId", "url", "position") SELECT "id", p.url, p.position FROM "Car", (VALUES ('photo-1612825173281-9a193378527e', 0), ('photo-1657217674164-9cbf85acfc6d', 1), ('photo-1621285853634-713b8dd6b5fd', 2), ('photo-1600510424051-30d592a75353', 3)) AS p(url, position) WHERE "slug" = 'lamborghini-huracan-evo';
INSERT INTO "Car" ("slug", "brand", "model", "year", "pricePerDay", "fuel", "seats", "horsepower", "acceleration", "topSpeed", "transmission", "drive", "range", "city", "pickupAddress", "pickupLat", "pickupLng", "hostName", "hostRating", "hostTrips", "description", "descriptionRo", "descriptionRu", "features", "updatedAt") VALUES ('audi-rs-e-tron-gt', 'Audi', 'RS e-tron GT', 2024, 6100, 'Electric'::"Fuel", 4, 646, 3.3, 250, '2-speed automatic', 'AWD'::"Drive", 470, 'Chișinău', 'Calea Ieșilor 10, Chișinău', 47.0415, 28.8034, 'Clara H.', 4.9, 126, 'Electric grand touring with Audi quattro traction. Fast-charging up to 270 kW means a coffee break adds hundreds of kilometres, and the cabin is quiet, beautifully finished and comfortable for long days.', 'Grand touring electric cu tracțiunea quattro de la Audi. Încărcarea rapidă de până la 270 kW înseamnă că o pauză de cafea adaugă sute de kilometri, iar habitaclul e silențios, foarte bine finisat și confortabil pentru zile lungi.', 'Электрический гран-туризмо с полным приводом quattro от Audi. Быстрая зарядка до 270 кВт означает, что за кофе-паузу прибавляются сотни километров, а тихий, прекрасно отделанный салон комфортен даже в долгие дни.', ARRAY['270 kW fast charging', 'Matrix LED headlights', 'Bang & Olufsen audio', 'Heated & ventilated seats', 'Adaptive air suspension', 'Head-up display'], CURRENT_TIMESTAMP);
INSERT INTO "CarPhoto" ("carId", "url", "position") SELECT "id", p.url, p.position FROM "Car", (VALUES ('photo-1654853976163-7ecedd0dd4d3', 0), ('photo-1629897872216-47ceb52635ab', 1), ('photo-1629897874832-a2e2f0d3715d', 2), ('photo-1618849985511-7dbc48d7d2e4', 3)) AS p(url, position) WHERE "slug" = 'audi-rs-e-tron-gt';
INSERT INTO "Car" ("slug", "brand", "model", "year", "pricePerDay", "fuel", "seats", "horsepower", "acceleration", "topSpeed", "transmission", "drive", "range", "city", "pickupAddress", "pickupLat", "pickupLng", "hostName", "hostRating", "hostTrips", "description", "descriptionRo", "descriptionRu", "features", "updatedAt") VALUES ('ford-mustang-gt500', 'Ford', 'Mustang GT500', 2023, 3900, 'Petrol'::"Fuel", 4, 760, 3.6, 290, '7-speed dual-clutch', 'RWD'::"Drive", NULL, 'Cahul', 'Strada Republicii 6, Cahul', 45.9339, 28.2416, 'Mike T.', 4.7, 233, 'The most powerful Mustang ever built. A supercharged 5.2-litre V8 with 760 hp and a soundtrack to match. Best enjoyed on an open road with the drive modes set to Sport and the windows down.', 'Cel mai puternic Mustang construit vreodată. Un V8 de 5,2 litri cu compresor, 760 CP și un sunet pe măsură. Cel mai bine savurat pe un drum deschis, cu modul de condus pe Sport și geamurile coborâte.', 'Самый мощный Mustang в истории. 5,2-литровый V8 с компрессором, 760 л. с. и соответствующий звук. Лучше всего — на открытой дороге, в режиме Sport и с опущенными стёклами.', ARRAY['Supercharged V8', 'Recaro seats', 'Bang & Olufsen audio', 'Track apps', 'Launch control', 'Apple CarPlay'], CURRENT_TIMESTAMP);
INSERT INTO "CarPhoto" ("carId", "url", "position") SELECT "id", p.url, p.position FROM "Car", (VALUES ('photo-1611566026373-c6c8da0ea861', 0), ('photo-1626732288613-347e78fd139c', 1), ('photo-1669652081031-2de2d6e641a2', 2), ('photo-1603553329474-99f95f35394f', 3)) AS p(url, position) WHERE "slug" = 'ford-mustang-gt500';
INSERT INTO "Car" ("slug", "brand", "model", "year", "pricePerDay", "fuel", "seats", "horsepower", "acceleration", "topSpeed", "transmission", "drive", "range", "city", "pickupAddress", "pickupLat", "pickupLng", "hostName", "hostRating", "hostTrips", "description", "descriptionRo", "descriptionRu", "features", "updatedAt") VALUES ('bmw-ix-m60', 'BMW', 'iX M60', 2024, 4900, 'Electric'::"Fuel", 5, 619, 3.8, 250, 'Single-speed', 'AWD'::"Drive", 560, 'Orhei', 'Strada Vasile Mahu 120, Orhei', 47.3712, 28.8224, 'Nina F.', 4.8, 152, 'A spacious electric SUV with M-level performance. Five comfortable seats, a huge boot and a lounge-like cabin make it the ideal family road-trip car, and the long range means fewer charging stops.', 'Un SUV electric spațios, cu performanțe de nivel M. Cinci locuri confortabile, un portbagaj uriaș și un habitaclu ca un lounge îl fac ideal pentru excursii în familie, iar autonomia mare înseamnă mai puține opriri la încărcat.', 'Просторный электрический SUV с динамикой уровня M. Пять удобных мест, огромный багажник и салон-лаунж делают его идеальным для семейных путешествий, а большой запас хода — это меньше остановок на зарядку.', ARRAY['Panoramic sky lounge roof', 'Bowers & Wilkins audio', 'Driving Assistant Pro', 'Heated steering wheel', 'Air suspension', 'Towing hitch'], CURRENT_TIMESTAMP);
INSERT INTO "CarPhoto" ("carId", "url", "position") SELECT "id", p.url, p.position FROM "Car", (VALUES ('photo-1651078944944-5d5507799a51', 0), ('photo-1702139146899-df34319ede56', 1), ('photo-1642189673400-2c5f1253af27', 2), ('photo-1731988666722-f783057cda66', 3)) AS p(url, position) WHERE "slug" = 'bmw-ix-m60';
INSERT INTO "Car" ("slug", "brand", "model", "year", "pricePerDay", "fuel", "seats", "horsepower", "acceleration", "topSpeed", "transmission", "drive", "range", "city", "pickupAddress", "pickupLat", "pickupLng", "hostName", "hostRating", "hostTrips", "description", "descriptionRo", "descriptionRu", "features", "updatedAt") VALUES ('porsche-taycan-turbo-s', 'Porsche', 'Taycan Turbo S', 2024, 7900, 'Electric'::"Fuel", 4, 761, 2.8, 260, '2-speed automatic', 'AWD'::"Drive", 440, 'Chișinău', 'Bulevardul Decebal 99, Chișinău', 46.9911, 28.8592, 'Felix M.', 5, 87, 'Porsche''s electric flagship. Launch control delivers relentless acceleration, and it still handles like a Porsche thanks to rear-axle steering and active suspension. Charges from 10 to 80% in under 20 minutes.', 'Vârful de gamă electric Porsche. Launch control oferă o accelerație implacabilă, iar datorită direcției pe puntea spate și suspensiei active se conduce tot ca un Porsche. Se încarcă de la 10 la 80% în mai puțin de 20 de minute.', 'Электрический флагман Porsche. Launch control обеспечивает неумолимый разгон, а благодаря подруливающей задней оси и активной подвеске он управляется как настоящий Porsche. Заряжается с 10 до 80% меньше чем за 20 минут.', ARRAY['800-volt fast charging', 'Rear-axle steering', 'Burmester audio', 'Passenger display', 'Panoramic roof', 'Adaptive cruise control'], CURRENT_TIMESTAMP);
INSERT INTO "CarPhoto" ("carId", "url", "position") SELECT "id", p.url, p.position FROM "Car", (VALUES ('photo-1642911041553-297e5295276b', 0), ('photo-1570374910698-6db3d787e6fb', 1), ('photo-1618213221550-c32da08997db', 2), ('photo-1615125468484-088e3dfcabb6', 3)) AS p(url, position) WHERE "slug" = 'porsche-taycan-turbo-s';
INSERT INTO "Car" ("slug", "brand", "model", "year", "pricePerDay", "fuel", "seats", "horsepower", "acceleration", "topSpeed", "transmission", "drive", "range", "city", "pickupAddress", "pickupLat", "pickupLng", "hostName", "hostRating", "hostTrips", "description", "descriptionRo", "descriptionRu", "features", "updatedAt") VALUES ('mercedes-eqs-580', 'Mercedes', 'EQS 580', 2023, 5300, 'Electric'::"Fuel", 5, 523, 4.3, 210, 'Single-speed', 'AWD'::"Drive", 670, 'Ungheni', 'Strada Națională 15, Ungheni', 47.2076, 27.8009, 'Camille D.', 4.9, 119, 'The electric S-Class. Whisper-quiet, remarkably efficient and packed with technology, including the full-width Hyperscreen. With the longest range in our fleet, it is the calmest way to cross a country.', 'Clasa S electrică. Extrem de silențioasă, remarcabil de eficientă și plină de tehnologie, inclusiv Hyperscreen-ul pe toată lățimea bordului. Cu cea mai mare autonomie din flota noastră, este cel mai relaxat mod de a traversa o țară.', 'Электрический S-класс. Очень тихий, удивительно эффективный и полный технологий, включая Hyperscreen во всю ширину панели. С самым большим запасом хода в нашем автопарке это самый спокойный способ пересечь страну.', ARRAY['MBUX Hyperscreen', 'Massage seats', 'Burmester 3D audio', 'Rear-axle steering', 'Air suspension', 'Ambient lighting'], CURRENT_TIMESTAMP);
INSERT INTO "CarPhoto" ("carId", "url", "position") SELECT "id", p.url, p.position FROM "Car", (VALUES ('photo-1672644087841-7c28b3e501ee', 0), ('photo-1788873828604-9e5a7e2892db', 1), ('photo-1763761260582-11e073f7cd7f', 2), ('photo-1664463361754-315b94783b21', 3)) AS p(url, position) WHERE "slug" = 'mercedes-eqs-580';
INSERT INTO "Car" ("slug", "brand", "model", "year", "pricePerDay", "fuel", "seats", "horsepower", "acceleration", "topSpeed", "transmission", "drive", "range", "city", "pickupAddress", "pickupLat", "pickupLng", "hostName", "hostRating", "hostTrips", "description", "descriptionRo", "descriptionRu", "features", "updatedAt") VALUES ('ferrari-sf90-stradale', 'Ferrari', 'SF90 Stradale', 2023, 25400, 'Hybrid'::"Fuel", 2, 1000, 2.5, 340, '8-speed dual-clutch', 'AWD'::"Drive", 25, 'Soroca', 'Strada Independenței 32, Soroca', 48.1502, 28.3023, 'Marco P.', 5, 23, 'Ferrari''s plug-in hybrid hypercar. A twin-turbo V8 and three electric motors combine for 1,000 hp, yet it can glide silently through town on electric power alone. The most exclusive car in the collection.', 'Hypercarul plug-in hibrid de la Ferrari. Un V8 twin-turbo și trei motoare electrice însumează 1.000 CP, dar mașina poate rula silențios prin oraș doar pe energie electrică. Cea mai exclusivistă mașină din colecție.', 'Гибридный гиперкар Ferrari с подзарядкой от розетки. V8 битурбо и три электромотора выдают вместе 1000 л. с., но по городу он может бесшумно ехать только на электричестве. Самый эксклюзивный автомобиль в коллекции.', ARRAY['Plug-in hybrid', 'eDrive silent mode', 'Carbon fibre interior', 'Digital cockpit', 'Front lift system', 'Launch control'], CURRENT_TIMESTAMP);
INSERT INTO "CarPhoto" ("carId", "url", "position") SELECT "id", p.url, p.position FROM "Car", (VALUES ('photo-1675426513824-25a43c3ae0ba', 0), ('photo-1626995449612-aece6b418f55', 1), ('photo-1609138314972-08a5a13e88cf', 2), ('photo-1757102563392-6277ee4b2dca', 3)) AS p(url, position) WHERE "slug" = 'ferrari-sf90-stradale';
